static int
fd_exec_test_gossip_prune_data_encode( fd_pb_encoder_t * enc,
                                       void const *      msg_ ) {
  fd_exec_test_gossip_prune_data_t const * msg = msg_;
  if( msg->pubkey && msg->pubkey->size && FD_UNLIKELY( !fd_pb_push_bytes( enc, 1U, msg->pubkey->bytes, msg->pubkey->size ) ) ) return 0;
  for( ulong i=0UL; i<msg->prunes_count; i++ ) {
    if( FD_UNLIKELY( !fd_pb_enc_bytes_ptr( enc, 2U, msg->prunes[ i ] ) ) ) return 0;
  }
  if( msg->signature && msg->signature->size && FD_UNLIKELY( !fd_pb_push_bytes( enc, 3U, msg->signature->bytes, msg->signature->size ) ) ) return 0;
  if( msg->destination && msg->destination->size && FD_UNLIKELY( !fd_pb_push_bytes( enc, 4U, msg->destination->bytes, msg->destination->size ) ) ) return 0;
  if( msg->wallclock && FD_UNLIKELY( !fd_pb_push_uint64( enc, 5U, msg->wallclock ) ) ) return 0;
  return 1;
}

static int
fd_exec_test_gossip_prune_data_decode( fd_pb_inbuf_t * in,
                                       void *          msg_,
                                       fd_spad_t *     spad ) {
  fd_exec_test_gossip_prune_data_t * msg = msg_;
  while( fd_pb_inbuf_sz( in ) ) {
    fd_pb_tlv_t tlv[1];
    if( FD_UNLIKELY( !fd_pb_dec_tlv( in, tlv ) ) ) return 0;
    switch( tlv->field_id ) {
    case 1:
      if( FD_UNLIKELY( !fd_pb_dec_bytes_ptr( in, tlv, spad, &msg->pubkey ) ) ) return 0;
      break;
    case 2:
      {
        fd_pb_bytes_array_t ** ele = fd_pb_dec_grow( spad, &msg->prunes, &msg->prunes_count, alignof(fd_pb_bytes_array_t *), sizeof(fd_pb_bytes_array_t *) );
        if( FD_UNLIKELY( !ele ) ) return 0;
        if( FD_UNLIKELY( !fd_pb_dec_bytes_ptr( in, tlv, spad, ele ) ) ) return 0;
      }
      break;
    case 3:
      if( FD_UNLIKELY( !fd_pb_dec_bytes_ptr( in, tlv, spad, &msg->signature ) ) ) return 0;
      break;
    case 4:
      if( FD_UNLIKELY( !fd_pb_dec_bytes_ptr( in, tlv, spad, &msg->destination ) ) ) return 0;
      break;
    case 5:
      if( FD_UNLIKELY( !fd_pb_dec_uint64( tlv, &msg->wallclock ) ) ) return 0;
      break;
    default:
      if( FD_UNLIKELY( !fd_pb_dec_skip( in, tlv ) ) ) return 0;
      break;
    }
  }
  return 1;
}

