static int
fd_exec_test_gossip_msg_encode( fd_pb_encoder_t * enc,
                                void const *      msg_ ) {
  fd_exec_test_gossip_msg_t const * msg = msg_;
  if( msg->which_msg==1 && FD_UNLIKELY( !fd_pb_enc_submsg( enc, 1U, &fd_exec_test_gossip_ping_desc, &msg->msg.ping ) ) ) return 0;
  if( msg->which_msg==2 && FD_UNLIKELY( !fd_pb_enc_submsg( enc, 2U, &fd_exec_test_gossip_pong_desc, &msg->msg.pong ) ) ) return 0;
  if( msg->which_msg==3 && FD_UNLIKELY( !fd_pb_enc_submsg( enc, 3U, &fd_exec_test_gossip_pull_request_desc, &msg->msg.pull_request ) ) ) return 0;
  if( msg->which_msg==4 && FD_UNLIKELY( !fd_pb_enc_submsg( enc, 4U, &fd_exec_test_gossip_pull_response_desc, &msg->msg.pull_response ) ) ) return 0;
  if( msg->which_msg==5 && FD_UNLIKELY( !fd_pb_enc_submsg( enc, 5U, &fd_exec_test_gossip_push_message_desc, &msg->msg.push_message ) ) ) return 0;
  if( msg->which_msg==6 && FD_UNLIKELY( !fd_pb_enc_submsg( enc, 6U, &fd_exec_test_gossip_prune_message_desc, &msg->msg.prune_message ) ) ) return 0;
  return 1;
}

static int
fd_exec_test_gossip_msg_decode( fd_pb_inbuf_t * in,
                                void *          msg_,
                                fd_spad_t *     spad ) {
  fd_exec_test_gossip_msg_t * msg = msg_;
  while( fd_pb_inbuf_sz( in ) ) {
    fd_pb_tlv_t tlv[1];
    if( FD_UNLIKELY( !fd_pb_dec_tlv( in, tlv ) ) ) return 0;
    switch( tlv->field_id ) {
    case 1:
      if( msg->which_msg!=1 ) fd_memset( &msg->msg, 0, sizeof(msg->msg) );
      if( FD_UNLIKELY( !fd_pb_dec_submsg( in, tlv, spad, &fd_exec_test_gossip_ping_desc, &msg->msg.ping ) ) ) return 0;
      msg->which_msg = 1;
      break;
    case 2:
      if( msg->which_msg!=2 ) fd_memset( &msg->msg, 0, sizeof(msg->msg) );
      if( FD_UNLIKELY( !fd_pb_dec_submsg( in, tlv, spad, &fd_exec_test_gossip_pong_desc, &msg->msg.pong ) ) ) return 0;
      msg->which_msg = 2;
      break;
    case 3:
      if( msg->which_msg!=3 ) fd_memset( &msg->msg, 0, sizeof(msg->msg) );
      if( FD_UNLIKELY( !fd_pb_dec_submsg( in, tlv, spad, &fd_exec_test_gossip_pull_request_desc, &msg->msg.pull_request ) ) ) return 0;
      msg->which_msg = 3;
      break;
    case 4:
      if( msg->which_msg!=4 ) fd_memset( &msg->msg, 0, sizeof(msg->msg) );
      if( FD_UNLIKELY( !fd_pb_dec_submsg( in, tlv, spad, &fd_exec_test_gossip_pull_response_desc, &msg->msg.pull_response ) ) ) return 0;
      msg->which_msg = 4;
      break;
    case 5:
      if( msg->which_msg!=5 ) fd_memset( &msg->msg, 0, sizeof(msg->msg) );
      if( FD_UNLIKELY( !fd_pb_dec_submsg( in, tlv, spad, &fd_exec_test_gossip_push_message_desc, &msg->msg.push_message ) ) ) return 0;
      msg->which_msg = 5;
      break;
    case 6:
      if( msg->which_msg!=6 ) fd_memset( &msg->msg, 0, sizeof(msg->msg) );
      if( FD_UNLIKELY( !fd_pb_dec_submsg( in, tlv, spad, &fd_exec_test_gossip_prune_message_desc, &msg->msg.prune_message ) ) ) return 0;
      msg->which_msg = 6;
      break;
    default:
      if( FD_UNLIKELY( !fd_pb_dec_skip( in, tlv ) ) ) return 0;
      break;
    }
  }
  return 1;
}

