static int
fd_exec_test_gossip_effects_encode( fd_pb_encoder_t * enc,
                                    void const *      msg_ ) {
  fd_exec_test_gossip_effects_t const * msg = msg_;
  if( msg->valid && FD_UNLIKELY( !fd_pb_push_bool( enc, 1U, msg->valid ) ) ) return 0;
  if( msg->has_msg && FD_UNLIKELY( !fd_pb_enc_submsg( enc, 2U, &fd_exec_test_gossip_msg_desc, &msg->msg ) ) ) return 0;
  return 1;
}

